<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">metadata:</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> mapped:</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> 159744,</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> allocated:</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 346240</span></span>
